import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Interface guidelines","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-system.md","filePath":"developers/design-system.md","lastUpdated":1793111003000}'),d={name:"developers/design-system.md"};function n(r,e,i,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="interface-guidelines" tabindex="-1">Interface guidelines <a class="header-anchor" href="#interface-guidelines" aria-label="Permalink to &quot;Interface guidelines&quot;">​</a></h1><p>The workspace follows a neutral style in the spirit of <a href="https://ui.shadcn.com/" target="_blank" rel="noreferrer">shadcn/ui</a> (new-york, neutral base), implemented as plain CSS and Vue 3 components. There is no CSS framework or React runtime.</p><h2 id="where-things-live" tabindex="-1">Where things live <a class="header-anchor" href="#where-things-live" aria-label="Permalink to &quot;Where things live&quot;">​</a></h2><p>All paths are under <code>web/src</code>.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Contents</th><th>File</th></tr></thead><tbody><tr><td>Tokens</td><td>Colors, chart palette, radii, shadows, fonts (<code>--background</code>, <code>--muted-foreground</code>, <code>--radius-md</code>, …)</td><td><code>styles/ui.css</code> (<code>:root</code>)</td></tr><tr><td>Primitives</td><td>Buttons, inputs, selects, cards, badges, tabs, tables, lists, sidebar, stats and bars</td><td><code>styles/ui.css</code></td></tr><tr><td>Shell and overlays</td><td>Scrolling, sidebar collapse, mobile sheet, dialogs, menus, listboxes, toasts, skeletons</td><td><code>styles/app.css</code></td></tr><tr><td>Fonts</td><td>Self-hosted Geist and Geist Mono; Chinese falls back to the system sans-serif</td><td><code>styles/fonts.css</code></td></tr><tr><td>Shared components</td><td><code>UiSelect</code>, <code>UiMenu</code>, <code>UiSheet</code>, <code>AppDialog</code>, <code>Disclosure</code>, <code>StatusBadge</code>, <code>Toaster</code>, <code>Icon</code></td><td><code>components/</code></td></tr></tbody></table><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>Use the tokens; do not hard-code colors, radii, or shadows in a feature.</li><li>Reuse the primitives (<code>.btn</code>, <code>.input</code>, <code>.select</code>, <code>.card</code>, <code>.field</code>, <code>.page</code>, <code>.hdr</code>) and the shared components before adding a new class. Add page-specific styles next to the page rather than as overrides at the end of a stylesheet.</li><li>Body text and controls are 14px with 20px line height; metadata is 12px. On screens narrower than 900px, inputs use 16px text so mobile browsers do not zoom.</li><li>The sidebar is 288px and collapses fully; below 900px it becomes a sheet. Only the main inset scrolls; the sidebar history, dialogs, graphs, and bounded lists may scroll on their own.</li><li>Color never carries meaning alone: errors, statuses, and selections also have text or an icon. Network graphs keep categorical colors for node meaning; distribution charts use the blue chart palette.</li><li>Long-form review text keeps a reading size and line height instead of the denser card style.</li><li>The workspace has a light theme only.</li></ul><p>PaperSeek online builds on the same web sources, so visual changes belong in Community.</p><h2 id="checking-a-change" tabindex="-1">Checking a change <a class="header-anchor" href="#checking-a-change" aria-label="Permalink to &quot;Checking a change&quot;">​</a></h2><p>Run <code>npm run typecheck</code>, <code>npm run build</code>, and <code>npm run test:browser</code> in <code>web/</code>, then look at the change in a real browser at desktop and phone widths.</p>',10)])])}const m=t(d,[["render",n]]);export{u as __pageData,m as default};
